+                      { "box": { "id": "obj-4", "maxclass": "newobj", "text": "codebox", "numinlets": 4, "numoutlets": 1, "outlettype": [""], "patching_rect": [30.0, 90.0, 420.0, 200.0], "code": "// Gate generator with Single vs Multi distinction
// in1 = step phasor (0-1 per pulse from stepdiv~)
// in2 = gate type (0=rest, 1=single, 2=multi, 3=hold)
// in3 = gate length (0.01-1.0)
// in4 = stepcounter~ output (stage+pulse index signal)
//
// Single (1): gate on first pulse of stage only
// Multi (2): gate on every pulse
// Hold (3): gate always on (legato)
// Rest (0): no gate

History prev_counter(0);
History is_first_pulse(1);

phasor = in1;
gt = in2;
gl = clamp(in3, 0.01, 1.0);
counter = in4;

// Detect stage change: counter jumps indicate new stage
if (counter != prev_counter) {
    // stepcounter~ resets pulse count per stage
    // When counter wraps or changes, mark as first pulse
    is_first_pulse = 1;
} else if (phasor < 0.01) {
    // Phasor reset within same stage = subsequent pulse
    is_first_pulse = 0;
}
prev_counter = counter;

gate = 0;
if (gt < 0.5) {
    gate = 0;
} else if (gt < 1.5) {
    // Single: only gate on first pulse of stage
    gate = (phasor < gl) && is_first_pulse;
} else if (gt < 2.5) {
    // Multi: gate on every pulse
    gate = phasor < gl;
} else {
    // Hold: gate always on
    gate = 1;
}

out1 = gate;" } },

