-                      { "box": { "id": "obj-3", "maxclass": "newobj", "text": "codebox", "numinlets": 2, "numoutlets": 3, "outlettype": ["", "", ""], "patching_rect": [30.0, 90.0, 400.0, 200.0], "code": "// Note edge detector
History prev_gate(0);
History held_pitch(0);

pitch = round(clamp(in1, 0, 127));
gate = in2;

note_on = 0;
note_off = 0;

if (gate > 0.5 && prev_gate < 0.5) {
    note_on = pitch;
    held_pitch = pitch;
}
if (gate < 0.5 && prev_gate > 0.5) {
    note_off = held_pitch;
}
if (gate > 0.5 && prev_gate > 0.5 && pitch != held_pitch) {
    note_off = held_pitch;
    note_on = pitch;
    held_pitch = pitch;
}

prev_gate = gate;
out1 = note_on;
out2 = note_off;
out3 = held_pitch;" } },
